<?php
declare(strict_types=1);
require_once __DIR__.'/_bootstrap.php';require_once __DIR__.'/_layout.php';require_once __DIR__.'/../config/saas_billing.php';saas_billing_ensure_schema($pdo);$id=(int)($_GET['id']??$_POST['id']??0);$msg='';$erro='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['action']??'')==='sync'){$c=saas_sync_charge_status($pdo,$id);$msg='Status sincronizado.';}elseif(($_POST['action']??'')==='cancel'){$c=saas_cancel_open_charge($pdo,$id);$msg='Cobrança cancelada localmente.';}}$c=saas_get_charge($pdo,$id);if(!$c)throw new RuntimeException('Cobrança não encontrada.');}catch(Throwable $e){$erro=$e->getMessage();$c=$c??null;}
saas_layout_start('Cobrança','Detalhes da cobrança #'.$id,'Acompanhe o gateway, pagamento, QR Code e diagnóstico.');?><div class="top-actions"><a class="btn2 btn2-ghost" href="/saas/cobrancas.php">Voltar</a><?php if($c):?><form method="post"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="sync"><button class="btn2 btn2-ghost">Sincronizar</button></form><?php endif;?></div><?php if($msg):?><div class="alert-ok"><?=e($msg)?></div><?php endif;?><?php if($erro):?><div class="alert-err"><?=e($erro)?></div><?php endif;?><?php if($c):?><div class="grid-2" style="align-items:start"><div class="panel"><h3>Resumo</h3><p><strong>Empresa:</strong> <?=e((string)$c['company_name'])?></p><p><strong>Plano:</strong> <?=e((string)$c['plan_name'])?></p><p><strong>Valor:</strong> <?=money((float)$c['amount'])?></p><p><strong>Gateway:</strong> <?=e((string)$c['gateway'])?></p><p><strong>Forma:</strong> <?=e((string)$c['payment_method'])?></p><p><strong>Status local:</strong> <?=e((string)$c['status'])?></p><p><strong>Status gateway:</strong> <?=e((string)($c['gateway_status']??''))?></p><p><strong>ID externo:</strong> <code><?=e((string)$c['txid'])?></code></p><p><strong>Referência:</strong> <code><?=e((string)($c['gateway_reference']??''))?></code></p><p><strong>Criada em:</strong> <?=e(saas_datetime_br($c['created_at'] ?? null))?></p><p><strong>Paga em:</strong> <?=e(saas_datetime_br($c['paid_at'] ?? null))?></p><?php if(strtolower((string)$c['status'])!=='paid'&&strtolower((string)$c['status'])!=='canceled'):?><form method="post" onsubmit="return confirm('Cancelar esta cobrança localmente?')"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="cancel"><button class="btn2 btn2-danger">Cancelar cobrança</button></form><?php endif;?></div><div class="panel"><h3>Pagamento</h3><?php if(!empty($c['qr_image'])):?><img src="data:image/png;base64,<?=e((string)$c['qr_image'])?>" style="max-width:280px;width:100%;background:#fff;padding:12px;border-radius:16px"><?php endif;?><?php if(!empty($c['pix_copy_paste'])):?><label>Pix copia e cola</label><textarea id="pix" class="field" rows="7" readonly><?=e((string)$c['pix_copy_paste'])?></textarea><button class="btn2 btn2-ghost" type="button" onclick="navigator.clipboard.writeText(document.getElementById('pix').value)">Copiar Pix</button><?php endif;?><?php if(!empty($c['checkout_url'])):?><a class="btn2 btn2-dark" target="_blank" rel="noopener" href="<?=e((string)$c['checkout_url'])?>">Abrir checkout</a><?php endif;?><?php if(!empty($c['payment_url'])):?><a class="btn2 btn2-ghost" target="_blank" rel="noopener" href="<?=e((string)$c['payment_url'])?>">Abrir página pública</a><?php endif;?></div></div><div class="panel" style="margin-top:18px"><h3>Dados técnicos</h3><details><summary>Payload enviado</summary><textarea class="field" rows="15" readonly><?=e((string)($c['payment_payload']??''))?></textarea></details><details style="margin-top:12px"><summary>Última resposta do gateway</summary><textarea class="field" rows="15" readonly><?=e((string)($c['inter_response']??''))?></textarea></details><details style="margin-top:12px"><summary>Último webhook</summary><textarea class="field" rows="15" readonly><?=e((string)($c['webhook_payload']??''))?></textarea></details></div><?php endif;?><?php saas_layout_end(); ?>
